// Condense a captured conversation JSONL into a readable turn/tool trace.
// Usage: node condense.mjs <file> [maxTextChars] [--tools]
import { readFileSync } from 'node:fs';

const [file, maxRaw, ...flags] = process.argv.slice(2);
const MAX = Number(maxRaw ?? 900);
const showTools = flags.includes('--tools');

const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);
const clip = (s) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > MAX ? `${t.slice(0, MAX)}…[+${t.length - MAX}]` : t;
};

for (const raw of lines) {
  let e;
  try { e = JSON.parse(raw); } catch { continue; }
  const ts = (e.timestamp ?? '').slice(11, 19);
  const msg = e.message ?? e;
  const role = msg.role ?? e.type;
  const content = msg.content;
  if (typeof content === 'string') {
    console.log(`\n[${ts}] ${role}: ${clip(content)}`);
    continue;
  }
  if (!Array.isArray(content)) continue;
  for (const b of content) {
    if (b.type === 'text' && b.text?.trim()) console.log(`\n[${ts}] ${role}: ${clip(b.text)}`);
    else if (b.type === 'tool_use' && showTools) {
      const a = b.input ?? {};
      const brief = a.command ?? a.file_path ?? a.pattern ?? a.prompt ?? a.skill ?? a.question ?? JSON.stringify(a).slice(0, 200);
      console.log(`[${ts}]   > ${b.name}: ${clip(brief).slice(0, 300)}`);
    } else if (b.type === 'tool_result' && showTools) {
      const t = typeof b.content === 'string' ? b.content : JSON.stringify(b.content);
      if (b.is_error || /error|denied|refused|blocked|fail/i.test(t.slice(0, 300))) console.log(`[${ts}]   < ${clip(t).slice(0, 400)}`);
    }
  }
}

