1	import { basename } from 'node:path';
2	import { finding } from '../../../../../engine/checks/helpers/findings.mjs';
3	import { flowOf } from '../../../../../engine/checks/helpers/active-migrations.mjs';
4	import { stripComments } from '../../../../../engine/checks/helpers/code-scanning.mjs';
5	import { VERSION_SOURCE, versionFromLiteral, versionAbove, versionsEqual, isVersion } from '../../../../../engine/version.mjs';
6	import { declaredVersion as engineVersionIn } from './engine-release-record.mjs';
7	
8	// A MIGRATION RECORD'S `version` IS A PREDICTION, and nothing here priced it.
9	//
10	// `migrationApplies` is `record.version > the repo's installed version`, so a record
11	// reaches exactly the repos sitting below the number it declares. The number it must
12	// declare is therefore the one its flow will carry once the change lands - and for a
13	// PACK that number is cut by the pack-versions workflow AFTER the merge, never by the
14	// change itself. The author is predicting somebody else's next commit.
15	//
16	// Predict too low and the record is dead on arrival: every member already converged
17	// to that version is at-or-above it, so the record never vendors, never applies, and
18	// nothing is red at any point. #2300 carried the whole hazard by hand - a "Before
19	// merge" paragraph in its body saying to raise `60924.1` if a bump had cut that number
20	// first, re-verified in the session two and three-quarter hours later when the owner
21	// approved. That paragraph is what this rule replaces.
22	//
23	// Predicting HIGH is the safe direction and is not a finding: the record simply keeps
24	// applying until the flow climbs past it.
25	//
26	// WHAT IT DOES NOT JUDGE. A change that moves its own flow's version - an engine
27	// release, which bumps `ENGINE_VERSION` in the same commit - is no longer predicting
28	// anything, and the number to compare against is the one it is replacing. Out of scope
29	// rather than guessed at: `engine-release-record` beside this file owns that change.
30	const RECORD = /^(engine|packs\/[^/]+)\/migrations\/\d{4}-\d{2}-\d{2}-[^/]+\/migration\.mjs$/;
31	const ENGINE_VERSION_FILE = 'engine/version.mjs';
32	
33	// The record's `version` field, read the way the ENGINE reads it: a plain literal on
34	// its own line (`recordVersion` in active-migrations.mjs, which scrapes the source
35	// because every caller of the predicate is synchronous). A check accepting a looser
36	// spelling would pass a record the engine cannot price. The two readings are
37	// drift-guarded by a test running both over every record in the tree.
38	const VERSION_FIELD = new RegExp(String.raw`^\s*version:\s*'?(${VERSION_SOURCE})'?\s*,\s*$`, 'm');
39	export function recordDeclaredVersion(text) {
40	  if (typeof text !== 'string') return null;
41	  const m = VERSION_FIELD.exec(stripComments(text));
42	  return m ? versionFromLiteral(m[1]) : null;
43	}
44	
45	// A RELOCATED RECORD IS NOT A NEW PREDICTION. Git reports a move as an add, so the
46	// destination has no base and its long-settled version reads as one this change just
47	// chose. The id survives a move where the path does not, so the ids the change DELETED
48	// are what tells the two apart.
49	const ID_FIELD = /^\s*id:\s*'([^']+)'\s*,\s*$/m;
50	const declaredId = (text) => (typeof text === 'string' ? ID_FIELD.exec(stripComments(text))?.[1] ?? null : null);
51	
52	function relocatedIds(work) {
53	  const ids = new Set();
54	  for (const file of work.deleted ?? []) {
55	    if (!RECORD.test(file)) continue;
56	    const id = declaredId(work.readBase(file));
57	    if (id) ids.add(id);
58	  }
59	  return ids;
60	}
61	
